   652  void *  v_FindFunction  (IM3Module i_module, const char * const i_name)
   653  {
   654      for (u32 i = 0; i < i_module->numFunctions; ++i)
   655      {
   656          IM3Function f = & i_module->functions [i];
   657
   658          bool isImported = f->import.moduleUtf8 or f->import.fieldUtf8;
   659
   660          if (isImported)
   661              continue;
   662
   663          for (int j = 0; j < f->numNames; j++)
   664          {
   665              if (f->names [j] and strcmp (f->names [j], i_name) == 0)
   666                  return f;
   667          }
   668      }
   669
   670      return NULL;
   671  }
